using System;
using LinearAlgebra;
using LinearAlgebra.Sparse;
using NUnit.Framework;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// Entrywise norms (Norms.L1/L2/LInf) and pattern-preserving componentwise ops
// (mulInPlace/signFlipInPlace/absInPlace/addScaledInPlace) over doubleBSR. Every correctness
// case validates the sparse op against the dense reference on the ToDense expansion — the
// implicit-zero blocks are what make the sparse/dense equivalence non-trivial, so each test
// matrix omits at least one block. Correctness cases run inside a [BurstCompile] IJob; the
// pattern-mismatch guard runs on the managed thread with Assert.Throws (same split as
// SparseBSRTests).
public class doubleSparseCompNormsTests
{
    [BurstCompile(CompileSynchronously = true)]
    public struct SparseCompNormsTestJob : IJob
    {
        public enum TestType
        {
            NormsMatchDense,
            ScaleFlipAbs,
            AddScaledSamePattern,
            EmptyMatrixNorms,
        }

        public TestType Type;

        static double Tol() => 1e-11;

        public void Execute()
        {
            switch (Type)
            {
                case TestType.NormsMatchDense: NormsMatchDense(); break;
                case TestType.ScaleFlipAbs: ScaleFlipAbs(); break;
                case TestType.AddScaledSamePattern: AddScaledSamePattern(); break;
                case TestType.EmptyMatrixNorms: EmptyMatrixNorms(); break;
            }
        }

        // 2x2 grid of 2x2 blocks with block (1,0) omitted; values include negatives so the
        // abs-based norms are actually exercised.
        static doubleBSR BuildTestBSR(double scale)
        {
            const int BR = 2, BC = 2;
            var builder = new doubleBSRBuilder(2, 2, BR, BC, Allocator.Temp);

            var b00 = new doubleMxN(BR, BC, Allocator.Temp);
            var b01 = new doubleMxN(BR, BC, Allocator.Temp);
            var b11 = new doubleMxN(BR, BC, Allocator.Temp);
            for (int r = 0; r < BR; r++)
                for (int c = 0; c < BC; c++)
                {
                    b00[r, c] = scale * (double)(1 + r * BC + c);      //  1 ..  4
                    b01[r, c] = scale * (double)(-(5 + r * BC + c));   // -5 .. -8
                    b11[r, c] = scale * (double)(9 + r * BC + c);      //  9 .. 12
                }

            builder.AddBlock(0, 0, in b00);
            builder.AddBlock(0, 1, in b01);
            builder.AddBlock(1, 1, in b11);
            return builder.ToBSR(Allocator.Temp);
        }

        // Dense entrywise references computed directly on the expansion.
        static void DenseEntrywiseNorms(in doubleMxN d, out double l1, out double l2, out double lInf)
        {
            l1 = 0; l2 = 0; lInf = 0;
            for (int i = 0; i < d.M_Rows; i++)
                for (int j = 0; j < d.N_Cols; j++)
                {
                    double av = math.abs(d[i, j]);
                    l1 += av;
                    l2 += av * av;
                    if (av > lInf) lInf = av;
                }
            l2 = math.sqrt(l2);
        }

        void NormsMatchDense()
        {
            var A = BuildTestBSR((double)1);
            var dense = A.ToDense(Allocator.Temp);
            DenseEntrywiseNorms(in dense, out double l1, out double l2, out double lInf);

            Assert.IsTrue(math.abs(Norms.L1(in A) - l1) < Tol() * l1);
            Assert.IsTrue(math.abs(Norms.L2(in A) - l2) < Tol() * l2);
            Assert.IsTrue(math.abs(Norms.LInf(in A) - lInf) < Tol() * lInf);
        }

        void ScaleFlipAbs()
        {
            // mulInPlace: A *= -3, compare against dense expansion scaled the same way.
            var A = BuildTestBSR((double)1);
            var reference = A.ToDense(Allocator.Temp);
            A.mulInPlace((double)(-3));
            var scaled = A.ToDense(Allocator.Temp);
            for (int i = 0; i < reference.M_Rows; i++)
                for (int j = 0; j < reference.N_Cols; j++)
                    Assert.IsTrue(math.abs(scaled[i, j] - (double)(-3) * reference[i, j]) < Tol());

            // signFlipInPlace: back to +3 * reference.
            A.signFlipInPlace();
            var flipped = A.ToDense(Allocator.Temp);
            for (int i = 0; i < reference.M_Rows; i++)
                for (int j = 0; j < reference.N_Cols; j++)
                    Assert.IsTrue(math.abs(flipped[i, j] - (double)3 * reference[i, j]) < Tol());

            // absInPlace: |3 * reference|.
            A.absInPlace();
            var abs = A.ToDense(Allocator.Temp);
            for (int i = 0; i < reference.M_Rows; i++)
                for (int j = 0; j < reference.N_Cols; j++)
                    Assert.IsTrue(math.abs(abs[i, j] - math.abs((double)3 * reference[i, j])) < Tol());
        }

        void AddScaledSamePattern()
        {
            // Same builder recipe twice -> identical pattern, different values via scale.
            var y = BuildTestBSR((double)1);
            var x = BuildTestBSR((double)10);
            Assert.IsTrue(BSR.samePattern(in y, in x));

            var yDense = y.ToDense(Allocator.Temp);
            var xDense = x.ToDense(Allocator.Temp);

            double a = (double)0.5f;
            y.addScaledInPlace(a, in x);

            var result = y.ToDense(Allocator.Temp);
            for (int i = 0; i < result.M_Rows; i++)
                for (int j = 0; j < result.N_Cols; j++)
                    Assert.IsTrue(math.abs(result[i, j] - (yDense[i, j] + a * xDense[i, j])) < Tol());
        }

        void EmptyMatrixNorms()
        {
            // No blocks added: all-zero matrix, all norms exactly 0.
            var builder = new doubleBSRBuilder(2, 2, 2, 2, Allocator.Temp);
            var A = builder.ToBSR(Allocator.Temp);

            Assert.IsTrue(Norms.L1(in A) == (double)0);
            Assert.IsTrue(Norms.L2(in A) == (double)0);
            Assert.IsTrue(Norms.LInf(in A) == (double)0);
        }
    }

    // ---- correctness cases (Burst) -------------------------------------------------------

    [Test]
    public void NormsMatchDenseTest()
